package com.aiservice.infrastructure.persistence.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="documents")public class DocumentEntity{@Id public UUID id;@Column(name="owner_id",nullable=false)public UUID ownerId;@Column(name="original_name",nullable=false)public String originalName;@Column(name="content_type",nullable=false)public String contentType;@Column(name="size_bytes",nullable=false)public long size;@Column(name="storage_key",nullable=false,unique=true)public String storageKey;@Column(nullable=false)public String checksum;@Column(name="created_at",nullable=false)public Instant createdAt;}
